INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-001', 0, 'AI-проект «Футбол для тебя»', 'Сделал аналог киносервиса, только для любителей футбола. Выбираешь режим и сетка сама подстраивает под тебя матчи, футбольные события и факты. Помимо проекта забилдил лендинг с помощью вайбкодинга.', '["uxui","web"]', '["Вёрстка","AI","Анимация"]', '/images/football.png', 'https://next-level-landing-motion.vercel.app/');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-002', 1, 'Редизайн Stepik', 'Продумал много фичей, необходимость которых выяснил во время общения с пользователями. Добавил видеоредактор, сделал отображение настроек в одном месте, встроил продвижение в интерфейс и даже чаты. А для самого кейса сделал свои первые 3D.', '["uxui"]', '["3D","Дизайн-система"]', '/images/stepik.png', 'https://www.behance.net/gallery/237391379/UXUI-design-for-education-platform');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-003', 2, 'Фичи для веб-приложения Loginom', 'За 3 года работы пересобрал дизайн-систему приложения, реализовал более 10 фич и начал привлекать пользователей к обсуждению функционала. Выстроил процесс работы при реализации фронтенд-части.', '["uxui"]', '["Исследования","Дизайн-система"]', '/images/loginom-app.png', 'https://loginom.ru/');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-004', 3, 'Редизайн страницы скачивания платформы', 'Придумал новую концепцию, подготовил анимации и презентовал готовый лендинг (верстал с помощью Framer). Как итог — готовый адаптивный макет с готовой анимацией и системой для масштабирования.', '["web"]', '["3D","Дизайн-система"]', '/images/download-page.png', 'https://megaladata.com/download');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-005', 4, 'Визуал мероприятия', 'Придумал масштабируемую концепцию, которую использовали уже 2 года. В рамках события делали лендинг, картинки для соцсетей, печатную продукцию (визитки, программа, баннеры) и рекламные креативы.', '["web","creative"]', '["Печатное","Реклама"]', '/images/event-visual.png', 'https://day.loginom.ru/');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-006', 5, 'Лендинг мероприятия', 'Обновил стиль события, добавил узнаваемые атрибуты для дальнейшего масштабирования визуала и сделал адаптивные макеты.', '["web","creative"]', '["Стиль","Адаптивы"]', '/images/event-landing.png', 'https://tech.loginom.ru/');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-007', 6, 'Визуал телеграм-канала Loginom', 'Подготовил визуальные материалы для телеграм-канала Loginom и поддерживал единый стиль публикаций.', '["creative"]', '["Стиль","Соцсети"]', '/images/loginom-telegram.png', 'https://t.me/loginom');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-008', 7, 'Проект «Фигма для редакторов»', 'Пет-проект, который начался с курса на Stepik. Сейчас я еженедельно делаю посты в канал, продумываю стиль бренда, формирую контент-план, записываю подкасты, организую активности и общаюсь с экспертами и подрядчиками.', '["uxui","web","creative"]', '["Продвижение","Маркетинг","Бренд"]', '/images/figma-editors.png', 'https://proeditor-figma.ru/');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-009', 8, 'Бот «Фигма для редакторов»', 'Продумал визуал и механику взаимодействия. В боте есть игра с 7 вопросами, где пользователь может выбрать скидку на любой наш продукт. Сделал персонажа, сверстал с помощью Codex и протестировал работу.', '["uxui"]', '["Бот","AI","Геймификация"]', '/images/figma-editors-bot.png', 'https://t.me/FigmaForEditors_bot');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-010', 9, 'Проморолик', 'Сделал проморолик для пет-проекта «Фигма для редакторов».', '["motion"]', '["After Effects","Telegram"]', '/images/promo-video.png', 'https://t.me/proeditor_figma/1308');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-011', 10, 'Шот-челлендж', 'На протяжении двух месяцев еженедельно генерили шоты уровня Dribbble. Здесь и 3D, и исследования, и работа с референсами, и креатив на полную. По итогу сделал полноценный шот в Cinema 4D, чтобы закрепить навыки.', '["uxui","web","creative"]', '["3D","Исследования"]', '/images/shot-challenge.png', 'https://www.behance.net/gallery/244981355/Prodlenka-I');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-012', 11, 'Стили в веб-дизайне', 'Первая статья в журнале, где я добавил много примеров работающих сайтов и подготовил весь визуал в Figma.', '["article"]', '["Веб-дизайн","Tilda Education"]', '/images/web-design-styles.png', 'https://tilda.education/web-design-styles-for-sites');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-013', 12, 'Гайд по автолейаутам в Фигме', 'Сделал подробный скринкаст и самостоятельно собрал примеры, на которых показал работу функционала. Подготовил гифки, чтобы объяснить сложные вещи. В статье выступил экспертом, автором и редактором.', '["article"]', '["Figma","Tilda Education"]', '/images/figma-autolayouts.png', 'https://tilda.education/figma-autolayouts');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-014', 13, 'Как сделать презентацию в Figma Slides', 'Разобрал новый функционал Figma на практических примерах. Сам предложил тему, подготовил шаблоны и проанализировал, чем инструмент удобен и полезен сейчас.', '["article"]', '["Figma Slides","Tilda Education"]', '/images/figma-slides.png', 'https://tilda.education/figma-slides-presentations');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-015', 14, 'Азбука дизайна: главные принципы и законы', 'Рассказал об основных правилах дизайна, которые использую в работе. Также проанализировал современные сайты и добавил примеры, где эти правила применяются.', '["article"]', '["Основы дизайна","Tilda Education"]', '/images/design-principles.png', 'https://tilda.education/basics-of-design');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-016', 15, 'Что такое UX/UI и чем занимаются дизайнеры в этой сфере', 'Нашёл двух экспертов и вместе с ними рассказал о профессии, в которой сам работаю. Получилась статья, которая вошла в топ 2025 года.', '["article"]', '["UX/UI","Tilda Education"]', '/images/ux-ui.png', 'https://tilda.education/ux-ui-design');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-017', 16, 'Подборка лучших бесплатных кириллических шрифтов', 'Вместе с экспертом рассмотрели популярные кириллические шрифты. Показали много примеров и сделали статью, которую можно сохранять и открывать, когда выбираешь шрифт для дизайна.', '["article"]', '["Шрифты","Tilda Education"]', '/images/cyrillic-fonts.png', 'https://tilda.education/cyrillic-fonts');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-018', 17, 'Композиция в дизайне', 'Разобрал вместе с экспертом виды композиций и то, что важно запомнить. В итоге подготовили чек-лист для проверки композиции и рассказали, как сделать её близкой к идеальной.', '["article"]', '["Основы дизайна","Tilda Education"]', '/images/composition.png', 'https://tilda.education/design-composition');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-019', 18, 'Дизайнеры и нейросети: как специалисты из разных сфер используют ИИ', 'Собрал экспертов и расспросил, как они применяют ИИ в работе: в моушене, шрифтах, интерфейсах и графическом дизайне.', '["article"]', '["AI","Tilda Education"]', '/images/ai-designers.png', 'https://tilda.education/ai-and-designers');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-020', 19, 'Эмоции в дизайне: как передать нужное настроение на сайте', 'Вместе с экспертом из Альфа-Банка посмотрели на разные сайты и рассказали, как делать нескучный дизайн, выбирать нужную эмоцию и почему без неё макет получается невзрачным.', '["article"]', '["Эксперт","Tilda Education"]', '/images/emotional-design.png', 'https://tilda.education/emotional-design');
INSERT INTO cases (id, position, title, description, categories, tags, image, href) VALUES ('case-021', 20, 'Графический дизайнер: чем занимается, какие навыки нужны и как войти в профессию', 'С двумя экспертами погрузились в профессию и рассказали про обязанности, зарплаты, тренды и с чего начать путь в графический дизайн.', '["article"]', '["Графдизайн","Tilda Education"]', '/images/graphic-designer.png', 'https://tilda.education/graphic-designer');
